import {profileAt} from './height-profile.js?v=20261010-smooth-grid';
import {structureSettings} from './structure-settings.js?v=20261010-smooth-grid';
import {rampDistance} from './ramp-distance.js?v=20261010-smooth-grid';
// Seventh-order easing has zero grade, curvature and curvature change at
// both ramp ends. Reserve extra approach length rather than compressing it.
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n)),smooth=t=>t**4*(35+t*(-84+t*(70-20*t))),PEAK=2.1875;
export function createStructureProfile(g,controls,points,options){
 const scale=clamp(Number(options.scale)||.2,.02,10),width=Number(options.width)||12,total=g.length*scale,closed=g.closed,ranges=[],issues=[];
 const normalize=m=>closed?((m%total)+total)%total:clamp(m,0,total),distance=(a,b)=>closed?Math.min(Math.abs(a-b),total-Math.abs(a-b)):Math.abs(a-b);
 const original=m=>profileAt(g.elevationProfile,normalize(m)/scale).value,metric=rampDistance(g,scale,width);
 for(const control of controls){const settings=structureSettings(control.point.structure);if(settings.type==='none'||!total)continue;if(ranges.length>=16){issues.push('Use at most 16 bridge/tunnel spans per circuit.');break;}
  const center=normalize((Number.isFinite(settings.anchorProgress)?settings.anchorProgress*total:control.station*scale)+settings.offset),span=Math.min(settings.length,total*.35),half=span/2,core=g.samples.filter((p,i)=>distance(g.cumulative[i]*scale,center)<=half);let low=original(center),high=low;for(const p of core){low=Math.min(low,p.elevation||0);high=Math.max(high,p.elevation||0);}
  // Account for the height of another road passing beneath/above the span.
  for(const p of core.filter((p,i)=>i%4===0))for(const q of g.samples)if(Math.hypot(p.x-q.x,p.y-q.y)*scale<width+2){const h=(q.elevation||0)+(settings.type==='bridge'?1:-1)*width/2*Math.abs(Math.tan((q.bank||0)*Math.PI/180));low=Math.min(low,h);high=Math.max(high,h);}
  const roofRise=settings.type==='tunnel'&&settings.tunnelStyle==='arch'?Math.min(1.6,(width/2+1.8)*.18):0,minimumHeight=settings.clearance+(settings.type==='bridge'?.6:roofRise+1.8),height=Math.max(minimumHeight,settings.height??minimumHeight),level=settings.type==='bridge'?high+height:low-height;
  const rise=Math.max(Math.abs(level-low),Math.abs(level-high)),desired=PEAK*rise/(settings.grade/100)*settings.approach,start=center-half,end=center+half,desiredBefore=start-metric.station(metric.at(start)-desired),desiredAfter=metric.station(metric.at(end)+desired)-end,availableBefore=closed?total/2-half-1:start,availableAfter=closed?total/2-half-1:total-end,rampBefore=Math.max(.5,Math.min(desiredBefore,availableBefore)),rampAfter=Math.max(.5,Math.min(desiredAfter,availableAfter)),ramp=Math.max(rampBefore,rampAfter),budgetBefore=Math.max(.01,metric.at(start)-metric.at(start-rampBefore)),budgetAfter=Math.max(.01,metric.at(end+rampAfter)-metric.at(end)),estimatedGrade=PEAK*rise/Math.min(budgetBefore,budgetAfter)*100;
  if(!closed&&(center-half<0||center+half>total))issues.push(`Handle ${control.index+1}: move the ${settings.type} away from the road endpoint.`);
  ranges.push({index:control.index,type:settings.type,center,span,ramp,rampBefore,rampAfter,budgetBefore,budgetAfter,desiredRamp:Math.max(desiredBefore,desiredAfter),limited:rampBefore+1<desiredBefore||rampAfter+1<desiredAfter,level,height,minimumHeight,requestedHeight:settings.height,heightAdjusted:settings.height!==null&&settings.height<minimumHeight,clearance:settings.clearance,roofRise,bridgeStyle:settings.bridgeStyle,tunnelStyle:settings.tunnelStyle,targetGrade:settings.grade,estimatedGrade,ground:original(center)});
 }
 for(let i=0;i<ranges.length;i++)for(let j=i+1;j<ranges.length;j++)if(distance(ranges[i].center,ranges[j].center)<(ranges[i].span+ranges[j].span)/2+2)issues.push(`Structures at handles ${ranges[i].index+1} and ${ranges[j].index+1} overlap. Separate their covered spans.`);
 const ordered=[...ranges].sort((a,b)=>a.center-b.center),links=[];
 for(let i=0;i<(closed&&ordered.length>1?ordered.length:ordered.length-1);i++){const a=ordered[i],b=ordered[(i+1)%ordered.length],start=a.center+a.span/2,end=b.center-b.span/2+(i===ordered.length-1?total:0),length=end-start;if(length>2&&length<a.rampAfter+b.rampBefore){links.push({from:a.index,to:b.index,start,end,length,a:a.level,b:b.level,budgetStart:metric.at(start),budget:metric.at(end)-metric.at(start)});a.linkedAfter=true;b.linkedBefore=true;}}
 const linked=m=>{const value=normalize(m);for(const link of links){const station=closed&&value<link.start?value+total:value;if(station>=link.start&&station<=link.end)return {link,t:clamp((metric.at(station)-link.budgetStart)/(link.budget||1),0,1)};}return null;};
 const influence=(range,m)=>{const value=normalize(m),delta=closed?((value-range.center+total/2)%total+total)%total-total/2:value-range.center,d=Math.abs(delta),before=delta<0,ramp=before?range.rampBefore:range.rampAfter;if(d<=range.span/2)return 1;if(d>=range.span/2+ramp)return 0;const edge=range.center+(before?-1:1)*range.span/2,station=range.center+delta,budget=before?metric.at(edge)-metric.at(station):metric.at(station)-metric.at(edge);return smooth(1-budget/(before?range.budgetBefore:range.budgetAfter));};
 function height(m){const connection=linked(m);if(connection)return connection.link.a+(connection.link.b-connection.link.a)*smooth(connection.t);const base=original(m);let value=base,den=1;for(const range of ranges){const w=influence(range,m);if(w>=1-1e-9)return range.level;const odds=w/(1-w);value+=range.level*odds;den+=odds;}return value/den;}
 function bank(m){if(linked(m))return 0;return profileAt(g.bankProfile,normalize(m)/scale).value*ranges.reduce((factor,range)=>factor*(1-influence(range,m)),1);}
 const derivative=(fn,u)=>{const m=u*scale,h=.05,a=closed?m-h:Math.max(0,m-h),b=closed?m+h:Math.min(total,m+h);return {value:fn(m),grade:(fn(b)-fn(a))/(b-a||1)*scale};};
 const sectionAt=m=>{let best=null;for(const range of ranges){const weight=influence(range,m);if(weight>0&&(!best||weight>best.weight))best={...range,weight,core:distance(normalize(m),range.center)<=range.span/2};}return best;};
 // Report the effective profile, including authored slopes and neighboring
 // ramp influence, instead of promising the requested grade was achieved.
 for(const range of ranges){const extent=range.span/2+range.ramp,count=Math.min(2400,Math.max(240,Math.ceil(extent*4)));let peak=0;for(let i=0;i<=count;i++){const m=range.center-extent+extent*2*i/count;peak=Math.max(peak,Math.abs(derivative(height,m/scale).grade)/scale*100);}range.actualGrade=peak;if(peak>12.05)issues.push(`Handle ${range.index+1}: the ${range.type} approaches exceed the 12% safety limit. Reduce height/depth, move the span or add approach space.`);}
 return {ranges,issues,links,total,scale,original,sectionAt,elevationAt:u=>derivative(height,u),bankAt:u=>derivative(bank,u)};
}
